    /// <summary>
    /// True when the CURRENT token is <paramref name="tokenType"/> AND that spelling is §8.9-reserved at the
    /// TARGETED edition — i.e. the word can only be the (unsupported) facility verb, never a user-defined
    /// word. Table-driven off the SAME SSOT the §8.9 funnel uses (ReservedWords.Find(...).IsReservedAt), so
    /// recognition and reservation can never diverge and NO per-word edition arithmetic leaks into the .g4.
    /// Read-only and allocation-free; safe for ANTLR's repeated prediction calls.
    /// </summary>
    protected bool facilityWord(int tokenType)
    {
        var t = CurrentToken;
        if (t is null || t.Type != tokenType) return false;
        return ReservedWords.Find(t.Text.ToUpperInvariant())?.IsReservedAt(Edition.Year) ?? false;
    }

