// SUPPRESS [PRINTING] (§14.9.45) — inhibit the presentation of the report group named by the enclosing
// USE BEFORE REPORTING declarative (§14.9.45.3 SR1, enforced at bind). PRINTING is an OPTIONAL word: the
// §14.9.45.2 format underlines only SUPPRESS, and §8.3.2.4.3 / §5.2.3 make non-underlined uppercase words
// optional — bare `SUPPRESS` is legal. Edition-invariant since COBOL-85 (Annex A.4.11 item 23): NO
// {isXXXX()}? gate and no VersionConformancePass ParseArm.
suppressStatement
    : SUPPRESS PRINTING?
    ;

semanticChanges.change:
Insert immediately after `BoundTerminate` (line 756):

/// <summary>SUPPRESS [PRINTING] (ISO §14.9.45): inhibit the presentation of the report group whose USE BEFORE
/// REPORTING procedure is executing (§14.9.45.3 SR1 — checked at bind). Only the REPORT is carried: the
/// suppression flag is a per-report engine flag armed and cleared around ONE BeforeReporting invocation, which
/// is precisely the §14.9.45.4 GR1 'the report group named in the USE procedure' + GR2 'the current instance'
/// scope — no group operand is needed or available (the statement has no operands).</summary>
public sealed record BoundSuppress(ReportModel Report) : BoundStatement;

Add after BindTerminate (line ~105), above `RwFindReport`:

/// <summary><c>SUPPRESS [PRINTING]</c> (ISO §14.9.45). SR1: the statement may appear ONLY in a USE BEFORE
/// REPORTING procedure — the same declarative probe RESUME's SR1 uses (EcBinder.BindResume), tightened by
/// requiring the declarative to be Format 2 (its ReportGroup is non-null): a Format 1/3/4 declarative is inside
/// the pc range but is not a BEFORE REPORTING procedure, so the EntryPc test alone is NOT sufficient.</summary>
public BoundStatement BindSuppress(Core.SuppressStatementContext stmt)
{
    var decl = ctx.Table.Declaratives.FirstOrDefault(
        d => ctx.BindCursor >= d.StartPc && ctx.BindCursor <= d.EndPc);
    if (ctx.BindCursor >= ctx.Table.EntryPc || decl?.ReportGroup is not { } group)
    {
        ctx.Edition.Error(DiagnosticCatalog.SuppressOutsideBeforeReporting,
            "SUPPRESS may be specified only in a USE BEFORE REPORTING procedure (ISO §14.9.45.3 SR1)");
        return new BoundNop();
    }
    // The group belongs to exactly one RD (ProcedureTableBuilder resolved it out of ctx.Data.Reports).
    if (ctx.Data.Reports.FirstOrDefault(r => r.Groups.Contains(group)) is not { } report)
        return new BoundUnsupported("SUPPRESS: the USE BEFORE REPORTING group has no owning report (internal)");
    return new BoundSuppress(report);
}

NOTE for the implementer: `ReportGroupModel` may not implement value equality — `r.Groups.Contains(group)` must be REFERENCE equality against the same instance ProcedureTableBuilder stored. If ReportGroupModel is a record with value equality, replace with `r.Groups.Any(g => ReferenceEquals(g, group))` to match the emitter's existing `r.Groups.IndexOf(hooked)` reference-identity assumption (ReportWriterEmitter.cs:271).

Add after EmitTerminate (line ~303):

/// <summary>SUPPRESS (ISO §14.9.45): arm the engine's current-presentation suppression flag. The flag is
/// cleared by the engine immediately BEFORE every BeforeReporting invocation and read immediately after, so
/// arming it is scoped to exactly the group named by the enclosing USE procedure (§14.9.45.4 GR1) and to
/// exactly that one presentation (GR2) — no per-group bookkeeping is emitted.</summary>
public void EmitSuppress(BoundSuppress s) =>
    ctx.Writer.Line($"__RPT_{s.Report.CsIndex}.Suppress();");

(1) Fix the STALE comment on ReportGroup.BeforeReporting (line 53): replace the parenthetical '(The SUPPRESS statement, §14.9.45, is not yet parsed — its suppression flag is staged with it.)' with '(A SUPPRESS statement, §14.9.45, executed inside this hook inhibits the group's presentation for this instance — see CobolReport.Suppress.)'.

(2) Add to CobolReport, beside the other private presentation state:

    // §14.9.45 — armed by a SUPPRESS executed inside the CURRENT group's BeforeReporting hook; cleared by
    // RunBeforeReporting before every invocation, which realizes GR2 ('limited to the current instance').
    private bool _suppressed;

    /// <summary>SUPPRESS [PRINTING] (ISO §14.9.45.1): inhibit the printing of the report group whose USE
    /// BEFORE REPORTING procedure is executing. GR1 scopes it to that group; GR2 scopes it to this one
    /// instance — both fall out of the arm-and-clear bracket in <see cref=\"RunBeforeReporting\"/>.</summary>
    public void Suppress() => _suppressed = true;

    /// <summary>Run a group's USE BEFORE REPORTING hook (ISO §14.9.49 Format 2 GR8) and report whether the
    /// group's presentation is suppressed (§14.9.45). The flag is cleared FIRST so only a SUPPRESS executed
    /// inside THIS invocation counts (GR2). ONE bracket for all four presentation paths — the singular
    /// pattern; no call site may invoke BeforeReporting directly.</summary>
    private bool RunBeforeReporting(ReportGroup g)
    {
        _suppressed = false;
        g.BeforeReporting?.Invoke();
        return _suppressed;
    }

(3) Replace ALL FOUR direct hook invocations with the bracket:

  a) PresentBody (line 320): replace `group.BeforeReporting?.Invoke();` with

        if (RunBeforeReporting(group))
        {
            // §14.9.45.4 GR3 inhibits exactly (a) printing the print lines, (b) any page advance associated
            // with the group, (c) NEXT GROUP processing, (d) any change to LINE-COUNTER — and §8.4.3.15.4 GR5
            // adds PAGE-COUNTER, equating a suppressed group to the dummy group handled just below. Returning
            // here achieves all four: the GR4 fit test (and its AdvancePage), every PresentLine (which is the
            // only writer of LineCounter), and the whole tail are skipped. GR3c is a cited no-op today —
            // NEXT GROUP stages loud at bind (COBOLNET0899 report-next-group).
            // NOT skipped: the SUM reset (§13.18.54.4 GR2) — it is absent from the exhaustive GR3 list, the
