    // ISO §12.4.5.7 GR6 — map each key-level clause's operands onto runtime key indices (-1 prime, i alt).
    var claimed = new Dictionary<int, string>();   // SR8 — a key named in more than one clause
    foreach (var (operands, alphaName, table, isNational) in file.KeyLevelCollating)
        foreach (var (opName, opQuals) in operands)
        {
            int? idx = null;
            if (file.RecordKeyName is { } rkn && Same(rkn, file.RecordKeyQualifiers, opName, opQuals)) idx = -1;
            else for (int i = 0; i < file.AlternateKeyNames.Count; i++)
                     if (Same(file.AlternateKeyNames[i].Name, file.AlternateKeyNames[i].Qualifiers, opName, opQuals)) { idx = i; break; }
            if (idx is null)
            {
                // SR4/SR5. Message must name the SOURCE non-support so a record-key-name-1 operand lands here
                // legibly (CONFORMANCE row 40 — the SOURCE key form is not provided, so no record-key-name can exist).
                Edition.Error("COBOLNET1579", $"file '{file.CobolName}': COLLATING SEQUENCE OF '{opName}' — the "
                    + "operand shall be a data-name specified in a RECORD KEY or ALTERNATE RECORD KEY clause of "
                    + "this file control entry (ISO §12.4.5.7 SR4/SR5; the record-key-name SOURCE key form is not "
                    + "provided — see CONFORMANCE.md A.3 item 40)");
                continue;
            }
            if (!claimed.TryAdd(idx.Value, opName))
                Edition.Error("COBOLNET1579", $"file '{file.CobolName}': key '{opName}' is specified in more than "
                    + "one COLLATING SEQUENCE clause (ISO §12.4.5.7 SR8)");
            // SR7 — the alphabet's class shall match the KEY's class.
            var keyItem = idx == -1 ? file.RecordKeyItem : (idx < file.AlternateKeys.Count ? file.AlternateKeys[idx].Item : null);
            bool keyIsNational = keyItem?.Pic?.Category is PictureCategory.National;   // use the project's existing category enum
            if (keyItem is not null && keyIsNational != isNational)
                Edition.Error("COBOLNET1579", $"file '{file.CobolName}': COLLATING SEQUENCE OF '{opName}' — a key of "
                    + $"class {(keyIsNational ? "national" : "alphanumeric")} requires an alphabet that defines a "
                    + $"{(keyIsNational ? "national" : "alphanumeric")} collating sequence (ISO §12.4.5.7 SR7)");
            file.PerKeyCollating[idx.Value] = keyIsNational ? null : table;   // national is vacuous (D-N2)
        }

